class VehicleProfileTruck(BaseModel):
    """
    Everything the `car` profile has, plus weight, dimensions, hazardous-goods, and toll/tunnel/highway parameters, for respecting road restrictions on heavy or hazardous-goods vehicles.

    > **When to use.** A vehicle-type name that is itself an unambiguous heavy-vehicle designation (a truck, lorry, semi-trailer, tractor-trailer, or equivalent) is sufficient evidence to pick `truck` even with no numeric dimensions yet.

    > **Default.** Setting `type: "truck"` and leaving every truck-only field unset does not apply any default legal-truck-road restriction; routing behaves exactly like `car` until one of those fields is actually set. Default to `car` when a vehicle's dimensions are genuinely unknown, and switch to `truck` once real dimensions or road restrictions are available.

    > **Modelling pitfall.** `height`, `width`, and `length` are whole centimetres, not metres: a truck 3.8 m tall is `height: 380`. A value in metres that happens to be a whole number, such as `length: 12`, raises no error and is read as 12 centimetres, so the vehicle's size no longer restricts its route. A decimal such as `4.2` is refused with a `400`. Round after converting from metres, for example `round(width_m * 100)`, because `2.55 * 100` is not exactly `255` in floating-point arithmetic.

    """

    model_config = ConfigDict(
        extra='allow',
    )
    type: Literal['truck'] = Field(
        ..., description='Discriminator identifying this vehicle profile as `truck`.'
    )
    grossWeight: Optional[float] = Field(
        None,
        description='Gross vehicle weight, in kilograms, used to respect weight-restricted roads.',
        examples=[12000],
    )
    withTraffic: Optional[bool] = Field(
        None,
        description='Enables predictive traffic in travel-time estimates (billed separately). For any plan where `preferredTimeWindows`/`authorizedTimeWindows` matter, travel-time estimates computed without it are systematically optimistic, which erodes on-time performance against exactly the time windows being targeted.\n',
    )
    avoidTollRoad: Optional[bool] = Field(
        None, description='Excludes toll roads from computed routes.'
    )
    avoidFerry: Optional[bool] = Field(
        None, description='Excludes ferry crossings from computed routes.'
    )
    avoidSeasonalClosure: Optional[bool] = Field(
        None, description='Excludes roads that are closed during part of the year.'
    )
    avoidControlledAccessHighway: Optional[bool] = Field(
        None,
        description='Excludes motorways and other controlled-access highways from computed routes.',
    )
    avoidCarShuttleTrain: Optional[bool] = Field(
        None, description='Excludes car-carrying shuttle trains from computed routes.'
    )
    avoidTunnel: Optional[bool] = Field(
        None, description='Excludes tunnels from computed routes.'
    )
    avoidDirtRoad: Optional[bool] = Field(
        None, description='Excludes unpaved or dirt roads from computed routes.'
    )
    avoidUTurns: Optional[bool] = Field(
        None, description='Excludes U-turns from computed routes.'
    )
    shippedHazardousGoods: Optional[List[ShippedHazardousGoodModel]] = Field(
        None,
        description='Categories of hazardous goods carried, used to respect roads restricted to those categories.',
        examples=[['explosive', 'gas', 'flammable']],
    )
    excludedCountries: Optional[CountryCodes] = Field(
        None, description='Countries to route around entirely.'
    )
    height: Optional[int] = Field(
        None,
        description='Vehicle height, as a whole number of centimetres, used to respect height-restricted roads such as low bridges.',
        examples=[420],
    )
    width: Optional[int] = Field(
        None,
        description='Vehicle width, as a whole number of centimetres, used to respect width-restricted roads.',
        examples=[250],
    )
    length: Optional[int] = Field(
        None,
        description='Vehicle length, as a whole number of centimetres, used to respect length-restricted roads.',
        examples=[1200],
    )
    tunnelCategory: Optional[TunnelCategory] = None
    speedCap: Optional[float] = Field(
        None,
        description='Maximum travel speed, in km/h, applied to every road segment regardless of its posted speed limit.',
        examples=[80],
    )


class TaggedCostFloorsAndCoeffs(CostFloorsAndCoeffs):
    """
    Cost floor and coefficient (see `CostFloorsAndCoeffs`), further scoped to the stop tags listed in `stopTags`.
    """

    model_config = ConfigDict(
        extra='allow',
    )
    stopTags: Optional[List[RegexIdValidation]] = Field(
        None,
        description='Stop tags this cost applies to.\n\n> **Default.** If empty or omitted, the cost applies regardless of stop tag.\n\n> **Modelling pitfall.** A tag that no stop carries makes the cost zero, with no error. Floors apply to the total of the matching stops only.\n',
        examples=[['warehouse', 'stop']],
    )


class Cost(BaseModel):
    """
    Cost structure of a resource. Fields are cumulative: the total cost of a tour is the sum of the contributions of every field that is set.

    > **Modelling pitfall.** Each field applies to a different base. The same cost must be expressed only once; setting both `using` and a `costFloor` on `km` applies a flat cost and a floor to the same distance rather than two independent contributions.

    """

    model_config = ConfigDict(
        extra='allow',
    )
    workedHours: Optional[CostFloorsAndCoeffs] = Field(
        None,
        description='Cost proportional to worked hours, in currency unit per hour.',
    )
    km: Optional[CostFloorsAndCoeffs] = Field(
        None,
        description='Cost proportional to travelled distance, in currency unit per kilometre.',
    )
    using: Optional[float] = Field(
        None,
        description='Flat cost added once per resource actually used in the plan, in currency unit.\n\n> **Modelling pitfall.** Independent of distance, duration, and capacity. A per-kilometre rate belongs in `km`, an hourly rate in `workedHours`.\n',
        examples=[120],
    )
    costsByStopTag: Optional[Dict[str, CostFloorsAndCoeffs]] = Field(
        None,
        description='Additional cost floors and coefficients on the stops that carry a given tag, by stop tag. The base is the number of visited stops carrying that tag, and floors apply once to the tour total.\n\n> **Modelling pitfall.** `constantCost` is paid once per tour that visits at least one stop of the tag, never once per stop. A tour with no stop of the tag pays nothing. An amount per stop goes in `costCoeff`.\n',
        examples=[{'warehouse': {'costCoeff': 5}}],
    )
    costsByCapacity: Optional[Dict[str, TaggedCostFloorsAndCoeffs]] = Field(
        None,
        description="Additional cost floors and coefficients on the quantities handled at the tour's stops, by capacity name, further scoped to specific stop tags. Each stop adds the absolute value of its quantity, whatever its `kind` or sign, and floors apply once to the tour total.\n\n> **Modelling pitfall.** The base is the quantity handled, not the vehicle's load: loading at departure doesn't count, and a pickup and a delivery of the same 100 units count 200. It applies to any capacity the stops carry, declared on the resource or not, and a tour that handles none of the capacity pays no `constantCost`. A minimum that must also hold on such a tour comes from `using`, because `costFloor` only delays `costCoeff`.\n",
        examples=[{'weight': {'stopTags': ['warehouse'], 'costCoeff': 0.1}}],
    )
    costPerCapacityPerTravelledKm: Optional[Dict[str, CostFloorsAndCoeffs]] = Field(
        None,
        description='Contribution to cost proportional to travelled distance and transported capacity, in currency unit per capacity unit per kilometre (for example `EUR/tonne/km`). For each capacity, the contribution is `costCoeff x distance(km) x transportedCapacity`.\n\n> **Default.** Cumulable with `costPerCapacityPerTravelledHour` and with the other cost fields; the two travelled-cost maps are independent.\n',
        examples=[{'weight': {'costCoeff': 0.2}, 'volume': {'costCoeff': 0.1}}],
    )
    costPerCapacityPerTravelledHour: Optional[Dict[str, CostFloorsAndCoeffs]] = Field(
        None,
        description='Contribution to cost proportional to travel duration and transported capacity, in currency unit per capacity unit per hour (for example `EUR/tonne/h`). For each capacity, the contribution is `costCoeff x travelDuration(h) x transportedCapacity`.\n\n> **Modelling pitfall.** The "Travelled" qualifier means travel duration only, not total working time; it does not include service time or waiting.\n',
        examples=[{'weight': {'costCoeff': 0.05}}],
    )


